'use strict';
let planSignature='';
function renderPlanner(){
 if(!progress||!catalog.length){$('#plan-results').textContent='Collega un salvataggio per pianificare gli sblocchi mancanti.';return;}
 const picker=$('#plan-character');
 if(picker.options.length===0){for(const name of [...new Set(catalog.map(r=>r.character).filter(Boolean))].sort()){const option=document.createElement('option');option.value=option.textContent=name;picker.append(option);}picker.value='Isaac';}
 const goalPicker=$('#plan-goal'),oldGoal=goalPicker.value;const eligible=catalog.filter(r=>r.character===picker.value&&!unlocked(r));const goalKey=JSON.stringify([picker.value,progress.hash]);if(goalPicker.dataset.key!==goalKey){goalPicker.innerHTML='<option value="">Massimizza gli sblocchi mancanti</option>'+eligible.map(r=>`<option value="${r.id}">${escapeHTML(r.name)}</option>`).join('');goalPicker.value=eligible.some(r=>String(r.id)===oldGoal)?oldGoal:'';goalPicker.dataset.key=goalKey;}
 const plans=AtlasPlanner.plans(catalog,progress.unlocked,picker.value,$('#plan-difficulty').value,[...saved]);
 const signature=JSON.stringify([slot,source,progress.hash,picker.value,$('#plan-difficulty').value,[...saved],goalPicker.value]);if(signature===planSignature)return;planSignature=signature;
 $('#plan-results').innerHTML=plans.filter(p=>p.rows.length&&(!goalPicker.value||p.rows.some(r=>String(r.id)===goalPicker.value))).map((p,i)=>`<details class="route-plan" ${i===0?'open':''}><summary><strong>${escapeHTML(p.name)}</strong><span>${p.core.length} obiettivi sul percorso · ${p.conditional.length} opzionali</span></summary><div class="route-body"><h3>Passaggi del percorso standard</h3><ol>${p.steps.map(step=>`<li>${escapeHTML(step)}</li>`).join('')}</ol><h3>Prima di partire</h3><ul>${p.requirements.map(step=>`<li>${escapeHTML(step)}</li>`).join('')}</ul><p class="meta">Prerequisiti da verificare: questa proposta non garantisce che tutte le aree siano accessibili sul tuo salvataggio.</p><div class="plan-objectives">${p.rows.map(r=>`<button data-detail="${r.id}">${escapeHTML(r.name)}${saved.has(r.id)?' · Da provare':''}<small>${escapeHTML(r.bosses.join(' + '))}${p.conditional.includes(r)?' · accesso opzionale/condizionale':''}</small></button>`).join('')}</div><a class="text-button" href="https://bindingofisaacrebirth.wiki.gg/wiki/${p.source}" target="_blank" rel="noopener noreferrer">Fonte del percorso ↗</a></div></details>`).join('')||'<p>Nessuna proposta compatibile con questi filtri. Gli obiettivi cumulativi o che richiedono più percorsi restano consultabili nel catalogo.</p>';
}
for(const id of ['plan-character','plan-difficulty','plan-goal'])$('#'+id).addEventListener('change',renderPlanner);
$('#open-planner').addEventListener('click',()=>{$('#planner').open=true;renderPlanner();$('#planner').scrollIntoView({behavior:'smooth',block:'start'});});
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-plan]');if(!trigger)return;const r=catalog.find(r=>r.id===Number(trigger.dataset.plan));if(!r)return;$('#detail').close();$('#planner').open=true;renderPlanner();if(r.character)$('#plan-character').value=r.character;$('#plan-difficulty').value=/greedier/i.test(r.requirement)?'greedier':/greed/i.test(r.requirement)?'greed':'hard';renderPlanner();$('#plan-goal').value=String(r.id);renderPlanner();$('#planner').scrollIntoView({behavior:'smooth',block:'start'});});
setInterval(renderPlanner,1500);
